#!/usr/bin/env node
// Generates src/model/logic.generated.js from the logic class in mockups/portal/Main.dc.html, so the mockup stays the
// single source until the API exists. With --check it fails if the generated file is out of date.
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const app = join(dirname(fileURLToPath(import.meta.url)), "..");
const source = readFileSync(join(app, "..", "mockups", "portal", "Main.dc.html"), "utf8");
const output = join(app, "src", "model", "logic.generated.js");

// A script tag, read as HTML reads it: a ">" inside a quoted attribute does not end the tag, and a comment is no tag.
const SCRIPT_TAG = /<!--[\s\S]*?-->|<script\b(?:[^>"']|"[^"]*"|'[^']*')*>/gi;
const ENTITIES = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'" };

/** An attribute value holds HTML entities, as DOMParser would decode them in dc-lite. */
function decodeEntities(text) {
  return text.replace(/&(?:#x([0-9a-f]+)|#(\d+)|(amp|lt|gt|quot|apos));/gi, (match, hex, dec, name) => {
    if (hex) return String.fromCodePoint(parseInt(hex, 16));
    if (dec) return String.fromCodePoint(Number(dec));
    return ENTITIES[name.toLowerCase()];
  });
}

const tag = [...source.matchAll(SCRIPT_TAG)].find((m) => m[0].startsWith("<script") && /\sdata-dc-script[\s=>]/i.test(m[0]));
if (!tag) throw new Error("no <script data-dc-script> in Main.dc.html");
const start = tag.index + tag[0].length;
// The first closing tag ends the block, as in the HTML parser, whatever other scripts follow.
const end = source.toLowerCase().indexOf("</script", start);
if (end < 0) throw new Error("the logic script is never closed");
const script = source.slice(start, end);

const attr = /\sdata-props=(?:'([^']*)'|"([^"]*)")/i.exec(tag[0]);
if (!attr) throw new Error("no data-props on the logic script");
// Parsed and re-serialised, so the generated module can only ever hold data, never code the attribute smuggled in.
const props = JSON.stringify(JSON.parse(decodeEntities(attr[1] ?? attr[2])));

const body = script.replace(/^class Component extends DCLogic/m, "export class Component extends DCLogic");
if (body === script) throw new Error("no Component class found");
const generated = `// Generated by scripts/extract-model.mjs from mockups/portal/Main.dc.html. Do not edit.
import { DCLogic } from "./dclogic";
export const PROPS = ${props};
${body}`;

if (process.argv.includes("--check")) {
  if (!existsSync(output) || readFileSync(output, "utf8") !== generated) {
    console.error("src/model/logic.generated.js is out of date: run npm run model");
    process.exit(1);
  }
} else {
  writeFileSync(output, generated);
}
